<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>DancePro TV</title><link rel="stylesheet" href="/tv-assets/player.css"></head>
<body data-preview="{{ $previewEvent ? 'true' : 'false' }}" data-manifest="{{ $previewEvent ? route('admin.publicity.manifest', $previewEvent, false) : '/api/publicity/screens/manifest' }}" data-images="{{ $previewEvent ? route('admin.publicity.image', ['schedulingEvent'=>$previewEvent, 'key'=>'__KEY__'], false) : '/api/publicity/screens/images/__KEY__' }}" data-videos="{{ $previewEvent ? route('admin.publicity.video', ['schedulingEvent'=>$previewEvent, 'key'=>'__KEY__'], false) : '/api/publicity/screens/videos/__KEY__' }}">
<main id="stage" aria-label="DancePro slideshow"><section id="welcome"><p class="brand">DANCEPRO TV</p><h1>{{ $previewEvent ? 'Preparing preview' : 'Your event on screen' }}</h1><p id="message">{{ $previewEvent ? 'Loading the current Top Pics and information slides…' : 'Pair this screen with an event in Publicity → TV Slideshows.' }}</p><strong id="pair-code" aria-live="polite"></strong></section><div class="frame" id="frame-a"></div><div class="frame" id="frame-b"></div></main><div id="branding" aria-label="Event branding"><img id="event-brand" alt="Event logo" hidden><img id="dancepro-brand" alt="DancePro Photography and Video" hidden></div>
<aside id="controls" aria-label="Playback controls"><div><strong>{{ $previewEvent ? 'Admin preview' : 'DancePro TV' }}</strong><span id="status" role="status">Preparing…</span></div><div class="buttons"><button id="pair" @if($previewEvent) hidden @endif>Pair screen</button><button id="pause">Pause</button><button id="next">Next slide</button><button id="fullscreen">Full screen</button><button id="refresh">Check for updates</button><button id="forget" @if($previewEvent) hidden @endif>Unpair &amp; clear this screen</button><button id="hide-controls">Hide controls</button></div><p id="help">Controls hide during playback. Press M or Escape to show them. Space pauses; arrow keys change slides.</p></aside>
<script type="module" src="/tv-assets/player.js"></script></body></html>
